#!/usr/bin/env node
'use strict';

// tools/radio-sim/bundle.js - prints simulate.js as ONE self-contained script that also carries
// v1.368.0's station picker (lib/music/radio.js) and its one repo dependency it needs whole
// (lib/music/tags.js parseYear), so `--picker new` runs inside the production container, where
// tools/ and the repo layout do not exist. The picker's sources are copied BYTE FOR BYTE from the
// repo at bundle time (never a hand copy); radio.js's other import, './store', is only used for
// albumKeyFor, which the bundle answers with simulate.js's own mirror (equivalence-checked at the
// kickoff). Usage:
//
//   node tools/radio-sim/bundle.js > radio-sim-bundle.js
//   docker exec -i <container> node - --data /app/data --picker new < radio-sim-bundle.js
//   docker exec -i <container> node - --data /app/data --stations < radio-sim-bundle.js   (v1.378.0 T0)

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..', '..');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
const MODULES = { './tags': 'lib/music/tags.js', './radio': 'lib/music/radio.js', './stations': 'lib/music/stations.js' }; // v1.378.0: the station builder rides too (--stations)

function bundle() {
  const sim = read('tools/radio-sim/simulate.js').replace(/^#!.*\n/, '');
  const factories = Object.entries(MODULES).map(([name, rel]) => `  ${JSON.stringify(name)}: function (module, exports, require) {\n// ---- ${rel}\n${read(rel)}\n  },`).join('\n');
  return `'use strict';
// GENERATED by tools/radio-sim/bundle.js - do not edit; regenerate from the repo.
function __RADIO_BUNDLE__(storeShim, name) {
  const factories = {
${factories}
  };
  const cache = {};
  function load(name) {
    if (name === './store') return storeShim;
    if (!Object.prototype.hasOwnProperty.call(factories, name)) return require(name);
    if (!cache[name]) { const m = { exports: {} }; cache[name] = m; factories[name](m, m.exports, load); }
    return cache[name].exports;
  }
  return load(name || './radio'); // v1.378.0: './stations' for the station census
}
${sim}`;
}

if (require.main === module) process.stdout.write(bundle());
module.exports = { bundle, MODULES };
